import Link from 'next/link';
import { cookies } from 'next/headers';
import { getSession } from './lib/auth';

export default async function Home({
  searchParams,
}: {
  searchParams: Promise<{ role?: string }>
}) {
  const { role } = await searchParams;
  const cookieStore = await cookies();

  if (role) {
    cookieStore.set('session_user_id', role === 'admin' ? 'admin-123' : 'user-123', {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      maxAge: 60 * 60 * 24,
    });

    cookieStore.set('session_role', role, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      maxAge: 60 * 60 * 24,
    });

    cookieStore.set('session_name', role === 'admin' ? 'Admin User' : 'John Doe', {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      maxAge: 60 * 60 * 24,
    });
  }

  const session = await getSession();

  return (
    <main style={{
      minHeight: '100vh',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      backgroundColor: '#f5f5f5',
      padding: '20px'
    }}>
      <div style={{
        backgroundColor: 'white',
        padding: '48px',
        borderRadius: '12px',
        boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
        textAlign: 'center',
        maxWidth: '500px',
        width: '100%'
      }}>
        <h1 style={{
          fontSize: '32px',
          fontWeight: '700',
          color: '#1f2937',
          marginBottom: '16px'
        }}>
          Welcome to the App
        </h1>

        {session ? (
          <div style={{ marginBottom: '32px' }}>
            <div style={{
              display: 'inline-flex',
              alignItems: 'center',
              gap: '8px',
              padding: '8px 16px',
              backgroundColor: session.role === 'admin' ? '#f0fdf4' : '#fef3c7',
              borderRadius: '20px',
              marginBottom: '16px'
            }}>
              <span style={{
                width: '10px',
                height: '10px',
                backgroundColor: session.role === 'admin' ? '#16a34a' : '#f59e0b',
                borderRadius: '50%'
              }}></span>
              <span style={{
                fontSize: '14px',
                fontWeight: '500',
                color: session.role === 'admin' ? '#166534' : '#92400e'
              }}>
                Logged in as {session.role}
              </span>
            </div>

            <p style={{ color: '#6b7280', fontSize: '16px' }}>
              Hello, <strong>{session.name}</strong>!
            </p>
          </div>
        ) : (
          <p style={{ color: '#6b7280', fontSize: '16px', marginBottom: '32px' }}>
            Sign in to access all features
          </p>
        )}

        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <Link
            href="/admin"
            style={{
              display: 'inline-flex',
              alignItems: 'center',
              justifyContent: 'center',
              padding: '14px',
              backgroundColor: '#4f46e5',
              color: 'white',
              borderRadius: '8px',
              textDecoration: 'none',
              fontWeight: '600',
              fontSize: '15px',
              transition: 'background-color 0.2s'
            }}
          >
            Go to Admin Dashboard
          </Link>

          {session && (
            <form action="/" method="GET">
              <button
                type="submit"
                name="logout"
                value="true"
                style={{
                  width: '100%',
                  padding: '14px',
                  backgroundColor: '#f3f4f6',
                  color: '#374151',
                  border: '1px solid #e5e7eb',
                  borderRadius: '8px',
                  cursor: 'pointer',
                  fontWeight: '500',
                  fontSize: '15px',
                  marginTop: '8px',
                  transition: 'background-color 0.2s'
                }}
              >
                Sign Out
              </button>
            </form>
          )}
        </div>

        <div style={{
          marginTop: '32px',
          paddingTop: '24px',
          borderTop: '1px solid #e5e7eb'
        }}>
          <Link
            href="/login"
            style={{
              color: '#6b7280',
              fontSize: '14px',
              textDecoration: 'none'
            }}
          >
            {session ? 'Switch Account' : 'Sign In →'}
          </Link>
        </div>
      </div>
    </main>
  );
}

